 $_SESSION['maintenance_mode']=$maintenance_mode;$_SESSION['email_notifications']=$email_notifications;$_SESSION['payment_notifications']=$payment_notifications;$_SESSION['order_notifications']=$order_notifications;$success='Settings saved successfully.';
